//! Free Pascal: `azul.pas` (unit `Azul`, generated by `doc/src/codegen/v2/lang_pascal`).
//!
//! Spellings: the "value layer" wraps each C function as the C name without
//! the underscore (`AzCssPropertyWidth(..)`, `AzPixelValuePx(100.0)`,
//! variant constructors `AzLayoutWidthPx(..)`), records are `TAz<Type>`,
//! C-like enums scoped (`TAzLayoutDisplay.Flex`, keywords get `_`), a
//! variant record has `Tag` and `Payload_<Variant>` fields. A record value
//! is only literal in a typed constant, so styles are built with statements
//! ([`super::linear`]); a Vec is copied from an `array[0..n-1] of TAzXxx`
//! (`AzXxxVecCopyFromPtr(@a[0], n)`); strings use `azul_string_from('..')`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use super::linear::{item_blocker, linear_comments, lower_to_statements, LinearSyntax};
use crate::codegen::{
    ir::{capitalize, snake_to_upper_camel, Item, Module, Prim},
    lang::{doubled_quote, variant_ctor_method},
    CodegenBackend, GeneratedFile,
};

/// The Pascal printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Pascal;

const KEYWORDS: &[&str] = &[
    "and", "array", "as", "asm", "begin", "case", "class", "const", "constructor", "destructor",
    "div", "do", "downto", "else", "end", "except", "exports", "file", "finalization",
    "finally", "for", "function", "goto", "if", "implementation", "in", "inherited",
    "initialization", "inline", "interface", "is", "label", "library", "mod", "nil", "not",
    "object", "of", "on", "operator", "or", "out", "packed", "procedure", "program", "property",
    "raise", "record", "repeat", "resourcestring", "self", "set", "shl", "shr", "string", "then",
    "threadvar", "to", "try", "type", "unit", "until", "uses", "var", "while", "with", "xor",
];

fn ident(name: &str) -> String {
    if KEYWORDS.contains(&name.to_ascii_lowercase().as_str()) {
        format!("{name}_")
    } else {
        name.to_string()
    }
}

impl LinearSyntax for Pascal {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "NaN".to_string(),
            "inf" => "Infinity".to_string(),
            "-inf" => "NegInfinity".to_string(),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "True" } else { "False" })
    }

    fn clike(&self, ty: &str, variant: &str) -> String {
        format!("TAz{ty}.{}", ident(variant))
    }

    fn type_name(&self, ty: &str) -> String {
        format!("TAz{ty}")
    }

    fn array_type(&self, elem: &str, n: usize) -> String {
        format!("array[0..{}] of TAz{elem}", n.saturating_sub(1))
    }

    fn call(&self, target: &str, class: &str, method: &str, args: &[String]) -> Vec<String> {
        let f = format!("Az{class}{}", snake_to_upper_camel(method));
        vec![format!("{target} := {};", pascal_call(&f, args))]
    }

    fn variant_call(&self, target: &str, ty: &str, variant: &str, args: &[String]) -> Vec<String> {
        let f = format!("Az{ty}{}", capitalize(&variant_ctor_method(variant)));
        vec![format!("{target} := {};", pascal_call(&f, args))]
    }

    fn union(
        &self,
        target: &str,
        _ty: &str,
        variant: &str,
        tag: usize,
        payload: Option<&str>,
    ) -> Vec<String> {
        let mut out = vec![
            format!("FillChar({target}, SizeOf({target}), 0);"),
            format!("{target}.Tag := {tag};"),
        ];
        if let Some(p) = payload {
            out.push(format!("{target}.Payload_{variant} := {p};"));
        }
        out
    }

    fn set_field(&self, target: &str, _ty: &str, field: &str, value: &str) -> String {
        format!("{target}.{} := {value};", ident(field))
    }

    fn set_elem(&self, arr: &str, index: usize, value: &str) -> String {
        format!("{arr}[{index}] := {value};")
    }

    fn vec_from_array(&self, target: &str, ty: &str, _elem: &str, arr: &str, count: &str) -> Vec<String> {
        vec![format!("{target} := Az{ty}CopyFromPtr(@{arr}[0], {count});")]
    }

    fn vec_empty(&self, target: &str, ty: &str) -> Vec<String> {
        vec![format!("{target} := Az{ty}Create;")]
    }

    fn string(&self, target: &str, s: &str) -> Vec<String> {
        vec![format!("{target} := azul_string_from({});", doubled_quote(s, '\''))]
    }
}

fn pascal_call(f: &str, args: &[String]) -> String {
    if args.is_empty() {
        f.to_string()
    } else {
        format!("{f}({})", args.join(", "))
    }
}

fn item_fn(item: &Item) -> (String, String) {
    let name = item.name.upper_camel();
    let ty = format!("TAz{}", item.ty);
    let decl = format!("function {name}: {ty};");
    let mut out = String::new();
    if let Some(reason) = item_blocker(&Pascal, item) {
        out.push_str(&format!(
            "{{ not expressible with the Pascal bindings: {} }}\n{decl}\nbegin\n  \
             FillChar(Result, SizeOf(Result), 0);\nend;\n",
            reason.replace('}', ")")
        ));
        return (decl, out);
    }
    let st = lower_to_statements(&Pascal, &item.value);
    for line in linear_comments(item, &st) {
        out.push_str(&format!("{{ {} }}\n", line.replace('}', ")")));
    }
    out.push_str(&decl);
    out.push('\n');
    if !st.decls.is_empty() {
        out.push_str("var\n");
        for (n, t) in &st.decls {
            out.push_str(&format!("  {n}: {t};\n"));
        }
    }
    out.push_str("begin\n");
    for s in &st.body {
        out.push_str(&format!("  {s}\n"));
    }
    out.push_str(&format!("  Result := {};\nend;\n", st.result));
    (decl, out)
}

impl CodegenBackend for Pascal {
    fn lang(&self) -> &'static str {
        "pascal"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["fpc", "freepascal", "delphi"]
    }

    fn display_name(&self) -> &'static str {
        "Pascal"
    }

    fn extension(&self) -> &'static str {
        "pas"
    }

    fn emit_module(&self, m: &Module) -> String {
        let fns: Vec<(String, String)> = m.items.iter().map(item_fn).collect();
        let mut out = String::from(
            "{ Generated by azul-css codegen (Pascal). Do not edit by hand. }\nunit \
             Styles;\n\n{$mode delphi}\n\ninterface\n\nuses Math, Azul;\n\n",
        );
        for (decl, _) in &fns {
            out.push_str(decl);
            out.push('\n');
        }
        out.push_str("\nimplementation\n");
        for (_, body) in &fns {
            out.push('\n');
            out.push_str(body);
        }
        out.push_str("\nend.\n");
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "{ Copy target/codegen/azul.pas and libazul here, then:\n    fpc -Mdelphi -Fl. \
             -k-L. -k-lazul main.pas && ./main }\nprogram Main;\n\n{$mode delphi}\n\nuses \
             Azul, Styles;\n\nvar\n",
        );
        for item in &m.items {
            main.push_str(&format!("  {}Value: TAz{};\n", item.name.upper_camel(), item.ty));
        }
        main.push_str("begin\n");
        for item in &m.items {
            let name = item.name.upper_camel();
            main.push_str(&format!(
                "  {name}Value := {name};\n  WriteLn('{name}: ', {name}Value.len, ' properties');\n"
            ));
        }
        main.push_str("end.\n");
        vec![
            GeneratedFile {
                path: "styles.pas".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.pas".to_string(),
                contents: main,
            },
        ]
    }
}
